changeSet.sql:
ALTER TABLE outbox_event
    ADD COLUMN attempt_count INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN next_attempt_at TIMESTAMPTZ,
    ADD COLUMN last_error TEXT,
    ADD COLUMN published_at TIMESTAMPTZ,
    ADD COLUMN dead_lettered_at TIMESTAMPTZ,
    ADD CONSTRAINT outbox_event_attempt_count_valid CHECK (attempt_count BETWEEN 0 AND 3);
ALTER TABLE outbox_event DROP CONSTRAINT outbox_event_delivery_state_valid;
ALTER TABLE outbox_event ADD CONSTRAINT outbox_event_delivery_state_valid
    CHECK (delivery_state IN ('PENDING', 'PUBLISHED', 'DEAD_LETTER_PENDING', 'DEAD_LETTERED'));
CREATE INDEX ix_outbox_event_delivery_ready ON outbox_event (delivery_state, next_attempt_at, created_at);
